    CHECK(http_query_get("t=0123456789abcdef", "t", v, sizeof v) == -1,
          "value of 16 bytes does not fit in 16 with its NUL");
    CHECK(http_query_get("t=0123456789abcde", "t", v, sizeof v) == 0, "value that just fits");
