    CHECK(parse("GET / FTP/1.1\r\n\r\n", &r) == HTTP_BAD, "not HTTP");
    CHECK(parse("GET  / HTTP/1.1\r\n\r\n", &r) == HTTP_BAD, "two spaces");
    CHECK(parse("GET index.html HTTP/1.1\r\n\r\n", &r) == HTTP_BAD, "target without a slash");
