    CHECK(parse("GET /%2E./x HTTP/1.1\r\n\r\n", &r) == HTTP_BAD, "half-encoded '..'");
    CHECK(parse("GET /a\\b HTTP/1.1\r\n\r\n", &r) == HTTP_BAD, "backslash");

