          "just under the cap, no end yet");
    CHECK(http_parse_request(big, HTTP_MAX_REQUEST, &r) == HTTP_TOO_LARGE,
          "at the cap with no end of headers");
    CHECK(http_parse_request(big, sizeof big, &r) == HTTP_TOO_LARGE, "far over the cap");

