static void test_write_head(void)
{
    char out[256];

    ssize_t n = http_write_head(out, sizeof out, 200, "text/html; charset=utf-8", 1234);
    const char *want =
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/html; charset=utf-8\r\n"
        "Content-Length: 1234\r\n"
        "Connection: close\r\n"
        "Cache-Control: no-store\r\n"
        "X-Content-Type-Options: nosniff\r\n"
        "\r\n";
    CHECK(n == (ssize_t)strlen(want), "length of the head");
    CHECK(n > 0 && memcmp(out, want, (size_t)n) == 0, "exact bytes of a 200 head");

    n = http_write_head(out, sizeof out, 404, "text/plain", 0);
    CHECK(n > 0 && strncmp(out, "HTTP/1.1 404 Not Found\r\n", 24) == 0, "404 status line");

    static const int known[] = { 200, 400, 404, 405, 431, 500 };
    for (size_t i = 0; i < sizeof known / sizeof known[0]; i++)
        CHECK(http_write_head(out, sizeof out, known[i], "text/plain", 0) > 0, "known status");
    CHECK(http_write_head(out, sizeof out, 418, "text/plain", 0) == -1, "unknown status");

