    CHECK(http_write_head(out, (size_t)n, 200, "text/plain", 5) == n, "buffer exactly big enough");
    CHECK(http_write_head(out, 0, 200, "text/plain", 5) == -1, "zero-size buffer");
}

int main(void)
{
    log_init("test_http", LOG_FATAL);
    test_good_requests();
    test_every_split_is_incomplete_until_whole();
    test_refusals();
    test_size_caps();
    test_refusals_are_statuses();
    test_query_get();
    test_write_head();
    return failures == 0 ? 0 : 1;
}

