                LOG_E("the listening socket failed (revents=%#x)", (unsigned)ev);
                return -1;
            }
            accept_new(s, now);
            handled++;
            continue;
        }
        if (c->state == CONN_FREE) continue;        /* reaped just now */
        handled++;
        if (c->state == CONN_READING) conn_read(s, c, now);
        else conn_write(s, c);
    }
