static void test_end_to_end(void)
{
    static const char *routes[] = { "/api/status", "/api/verdicts", "/api/faults",
                                    "/api/series?pid=0C", "/api/series?pid=probe&from=-1h" };
    static const char *verbs[] = { "status", "verdicts", "faults", "series pid=\"0C\"",
                                   "series pid=\"probe\" from=\"-1h\"" };
    static char reply[ROUTE_REPLY_MAX];

    use_synth();
    synth_set_time(&syn, NOW);
    for (size_t i = 0; i < sizeof routes / sizeof routes[0]; i++) {
        CHECK(call(routes[i]) == 200, routes[i]);
        CHECK(strcmp(resp.ctype, "application/json") == 0, "JSON");
        CHECK(starts(text, "{\"ok\":true,\"records\":[") && strcmp(text + strlen(text) - 2, "]}") == 0,
              "the envelope");
        CHECK(count(text, "{") == count(text, "}") && count(text, "[") == count(text, "]"),
              "braces balance");

        ssize_t n = source_query(&synth_src, verbs[i], reply, sizeof reply);
        size_t records = 0;
        for (const char *p = reply; (p = strchr(p, '\n')) != NULL; p++) records++;
        records--;   /* the terminator */
        CHECK(n > 0 && count(text, "{\"tag\":") == records, "one object per record");
        CHECK(count(text, "\"src\":\"synth\"") == records, "and every one says synth");
    }

    call("/api/status");
    CHECK(has("\"tag\":\"proc\",\"name\":\"obdd\",\"state\":\"up\",\"pid\":102"),
          "strings quoted, numbers not");
    CHECK(has("\"restarts\":2") && has("\"time_trusted\":1"), "numbers");
    call("/api/verdicts");
    CHECK(has("\"end_s\":null") && has("\"sensors\":\"coolant,intake\""), "null, and a list string");
    call("/api/series?pid=0C");
    CHECK(has("\"pid\":\"0C\"") && has("\"t_s\":18") && !has("\"t_s\":\""), "a PID is a string, a time a number");
    call("/api/series?pid=probe&from=-1h");
    CHECK(has("\"value\":null") && has("\"value\":2"), "the probe drops out, then answers");
}

static void test_conversion(void)
{
    use_fake("rec a=\"x\" n=1.5 z=null\nok\n");
    CHECK(call("/api/status") == 200, "ok");
    CHECK(strcmp(text, "{\"ok\":true,\"records\":[{\"tag\":\"rec\",\"a\":\"x\",\"n\":1.5,\"z\":null}]}") == 0,
          "each field keeps the type the source gave it");

    use_fake("ok\n");
    CHECK(call("/api/status") == 200 && strcmp(text, "{\"ok\":true,\"records\":[]}") == 0, "no records");

    use_fake("a n=1\nb n=2\nidle\nok\n");
    call("/api/status");
    CHECK(strcmp(text, "{\"ok\":true,\"records\":[{\"tag\":\"a\",\"n\":1},{\"tag\":\"b\",\"n\":2},"
                       "{\"tag\":\"idle\"}]}") == 0, "records in order, one with no fields");

    use_fake("a pid=\"46\" v=46\nok\n");
    call("/api/status");
    CHECK(has("\"pid\":\"46\",\"v\":46"), "a string that looks like a number stays a string");
}

static void test_error_mapping(void)
{
    static const struct { const char *reply; int status; const char *body; } cases[] = {
        { "err usage bad window\n", 400,
          "{\"ok\":false,\"code\":\"usage\",\"reason\":\"bad window\"}" },
        { "err unknown_pid no such pid\n", 404,
          "{\"ok\":false,\"code\":\"unknown_pid\",\"reason\":\"no such pid\"}" },
        { "err unknown_verb no such verb\n", 404,
          "{\"ok\":false,\"code\":\"unknown_verb\",\"reason\":\"no such verb\"}" },
        { "err unavailable storaged is down\n", 503,
          "{\"ok\":false,\"code\":\"unavailable\",\"reason\":\"storaged is down\"}" },
        { "err weird something odd\n", 500,
          "{\"ok\":false,\"code\":\"weird\",\"reason\":\"something odd\"}" },
        { "err usage\n", 400, "{\"ok\":false,\"code\":\"usage\",\"reason\":\"\"}" },
        { "rec a=1\nerr unavailable gone\n", 503,
          "{\"ok\":false,\"code\":\"unavailable\",\"reason\":\"gone\"}" },
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        use_fake(cases[i].reply);
        CHECK(call("/api/status") == cases[i].status, cases[i].reply);
        CHECK(strcmp(text, cases[i].body) == 0, "the error body");
        CHECK(strcmp(resp.ctype, "application/json") == 0, "JSON");
    }

    static const char *malformed[] = { "rec a=1\nbogus line\nok\n", "rec a=1\n", "", "ok\nrec a=1\n",
                                       "rec a=1\nok", "rec a=hello\nok\n" };
    for (size_t i = 0; i < sizeof malformed / sizeof malformed[0]; i++) {
        use_fake(malformed[i]);
        CHECK(call("/api/status") == 500 && json_error("internal"), malformed[i]);
    }

    use_fake("ok\n");
    fake.force = -1;
    CHECK(call("/api/status") == 500 && json_error("internal"), "a reply that did not fit");

    use_fake("rec tag=\"x\" a=1\nok\n");
    CHECK(call("/api/status") == 500 && json_error("internal"), "a field called tag collides with the record's");
}

static void test_request_lines(void)
{
    static const struct { const char *target, *line; } cases[] = {
        { "/api/status", "status" },
        { "/api/verdicts", "verdicts" },
        { "/api/faults", "faults" },
        { "/api/series", "series" },
        { "/api/series?pid=0C&from=-5m&to=now", "series pid=\"0C\" from=\"-5m\" to=\"now\"" },
        { "/api/series?to=now&from=-5m&pid=0C", "series pid=\"0C\" from=\"-5m\" to=\"now\"" },
        { "/api/series?pid=0C&from=1799999700&to=1800000000",
          "series pid=\"0C\" from=1799999700 to=1800000000" },
        { "/api/series?pid=04", "series pid=\"04\"" },
        { "/api/series?pid=46", "series pid=\"46\"" },
        { "/api/series?pid=probe&from=-1h", "series pid=\"probe\" from=\"-1h\"" },
        { "/api/series?from=10%3A30&pid=0C", "series pid=\"0C\" from=\"10:30\"" },
        { "/api/series?pid=0%43", "series pid=\"0C\"" },
        { "/api/series?pid=a%2Bb", "series pid=\"a+b\"" },
        { "/api/series?pid=aaaaaaaaaaaaaaaaaaaaaaaa", "series pid=\"aaaaaaaaaaaaaaaaaaaaaaaa\"" },
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        use_fake("ok\n");
        CHECK(call(cases[i].target) == 200, cases[i].target);
        CHECK(fake.calls == 1 && strcmp(fake.last, cases[i].line) == 0, cases[i].line);
        if (strcmp(fake.last, cases[i].line) != 0) fprintf(stderr, "  got: %s\n", fake.last);
    }
}

static void test_hostile_input_never_reaches_the_source(void)
{
    static const char *bad[] = {
        "/api/series?pid=0C%22", "/api/series?pid=0C\"x", "/api/series?pid=a%20b",
        "/api/series?pid=a+b", "/api/series?pid=%0A", "/api/series?pid=%09", "/api/series?pid=%00",
        "/api/series?pid=a%5Cb", "/api/series?pid=%FF", "/api/series?pid=",
        "/api/series?pid", "/api/series?pid=0C%22%20from%3D%221%22",
        "/api/series?pid=%3Cscript%3E", "/api/series?pid=a;b", "/api/series?pid=a%3Db",
        "/api/series?pid=%7B", "/api/series?pid=0C&to=a%26b", "/api/series?pid=aaaaaaaaaaaaaaaaaaaaaaaaa",
        "/api/series?pid=%zz", "/api/series?pid=%4", "/api/series?pid=0C&from=%zz",
        "/api/series?foo=1", "/api/series?pid=1&pid=2", "/api/series?PID=1", "/api/series?pid=1&",
        "/api/series?&pid=1", "/api/series?pid=1&&to=2", "/api/series?=1", "/api/series?pi=1",
        "/api/series?pids=1", "/api/series?pid=1&from=1&from=2", "/api/series?pid=1&to=1&to=2",
        "/api/status?x=1", "/api/verdicts?a", "/api/faults?since=-1h",
    };
    for (size_t i = 0; i < sizeof bad / sizeof bad[0]; i++) {
        use_fake("ok\n");
        CHECK(call(bad[i]) == 400 && json_error("usage"), bad[i]);
        CHECK(fake.calls == 0, "and the source was never asked");
    }

    use_fake("ok\n");
    CHECK(call("/api/status?") == 200 && fake.calls == 1, "an empty query is no query");
}

static void test_capacity(void)
{
    static char big[ROUTE_REPLY_MAX];
    size_t len = 0;

    /* A reply that fits the scratch buffer but whose JSON does not fit the response. */
    for (int i = 0; i < 2000 && len + 40 < sizeof big; i++)
        len += (size_t)snprintf(big + len, sizeof big - len, "r a=%d b=2 c=\"xxxxxxxx\"\n", i % 1000);
    snprintf(big + len, sizeof big - len, "ok\n");
    use_fake(big);
    CHECK(call("/api/status") == 500 && json_error("internal"), "a response too big for the body");

    use_fake("a n=1\nb n=2\nc n=3\nok\n");
    CHECK(call_cap("/api/status", 20) == 500, "a 20-byte body cannot hold the records");
    CHECK(call_cap("/api/status", 200) == 200, "200 bytes can");
    use_fake("err usage a long enough reason to overflow a tiny response buffer\n");
    CHECK(call_cap("/api/status", 30) == 500 && resp.body_len == 0, "even the error does not fit");
    CHECK(call_cap("/api/nope", 10) == 500, "nor the 404");
    CHECK(call_cap("/", 10) == 500, "nor the page");
}

int main(void)
{
    log_init("test_route", LOG_FATAL);
    test_paths();
    test_end_to_end();
    test_conversion();
    test_error_mapping();
    test_request_lines();
    test_hostile_input_never_reaches_the_source();
    test_capacity();
    return failures == 0 ? 0 : 1;
}

/* statusd's routes: see include/interface/route.h. No sockets, no allocation. */
#include "interface/route.h"
#include "interface/json.h"
#include "interface/kv.h"
#include "common/log.h"

#include <stdbool.h>
#include <stdio.h>
#include <string.h>

#define ROUTE_VALUE_MAX   24u    /* a query value, after decoding */
#define ROUTE_LINE_MAX    160u   /* the request line built from a URL */

/* PLACEHOLDER. "/" serves this stub until the real status page exists. It is replaced by
 * page.c in the "add the status page" commit, step 7 of the statusd series on branch
 * lance/m3/statusd (milestone M3, board item `statusd`). Delete this string, and the
 * "statusd" check in tests/test_route.c, in that commit. */
static const char placeholder_page[] =
    "<!doctype html>\n"
    "<html lang=\"en\"><head><meta charset=\"utf-8\">"
    "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
    "<title>carwatch</title></head>\n"
    "<body><h1>carwatch</h1>\n"
    "<p>statusd is running. The status page is not built yet; the data is at "
    "<a href=\"/api/status\">/api/status</a>. All of it is synthetic.</p>\n"
    "</body></html>\n";

static const struct { const char *path, *verb; } api[] = {
    { "/api/status",   "status" },
    { "/api/verdicts", "verdicts" },
    { "/api/faults",   "faults" },
    { "/api/series",   "series" },
};
#define NAPI (sizeof api / sizeof api[0])

/* The query keys /api/series takes, in the order they go into the request line. */
static const char *const series_keys[] = { "pid", "from", "to" };
#define NSERIES_KEYS (sizeof series_keys / sizeof series_keys[0])

/* --------------------------------------------------------------- responses */

static void set_empty_500(server_response_t *r)
{
    r->status = HTTP_STATUS_INTERNAL_ERROR;
    r->ctype = "text/plain";
    r->body_len = 0;
}

static void set_text(server_response_t *r, int status, const char *ctype, const char *text)
{
    size_t n = strlen(text);

    if (n > r->cap) { set_empty_500(r); return; }
    memcpy(r->body, text, n);
    r->status = status;
    r->ctype = ctype;
    r->body_len = n;
}

/* {"ok":false,"code":"...","reason":"..."} */
static void set_error(server_response_t *r, int status, const char *code, const char *reason)
{
    json_t j;

    json_init(&j, r->body, r->cap);
    json_begin_object(&j);
    json_key(&j, "ok");
    json_bool(&j, false);
    json_key(&j, "code");
    json_string(&j, code);
    json_key(&j, "reason");
    json_string(&j, reason);
    json_end_object(&j);
    ssize_t n = json_finish(&j);
    if (n < 0) { set_empty_500(r); return; }
    r->status = status;
    r->ctype = "application/json";
    r->body_len = (size_t)n;
}

static int status_for_code(const char *code)
{
    if (strcmp(code, "usage") == 0) return HTTP_STATUS_BAD_REQUEST;
    if (strcmp(code, "unknown_pid") == 0 || strcmp(code, "unknown_verb") == 0)
        return HTTP_STATUS_NOT_FOUND;
    if (strcmp(code, "unavailable") == 0) return HTTP_STATUS_UNAVAILABLE;
    return HTTP_STATUS_INTERNAL_ERROR;
}

/* The source's records as {"ok":true,"records":[{"tag":...,<fields>}]}. Returns false, with
 * the reason in *why, if the reply cannot be shown. */
static bool records_to_json(server_response_t *r, const char *reply, size_t n, const char **why)
{
    const char *cur = reply, *end = reply + n;
    kv_line_t rec;
    json_t j;

    json_init(&j, r->body, r->cap);
    json_begin_object(&j);
    json_key(&j, "ok");
    json_bool(&j, true);
    json_key(&j, "records");
    json_begin_array(&j);
    while (kv_reply_next(&cur, end, &rec) == KV_RECORD) {
        if (kv_get(&rec, "tag") != NULL) {
            LOG_E("source record %s has a field called tag", rec.tag);
            *why = "source sent a field named tag";
            return false;
        }
        json_begin_object(&j);
        json_key(&j, "tag");
        json_string(&j, rec.tag);
        for (size_t i = 0; i < rec.nfields; i++) {
            json_key(&j, rec.f[i].key);
            switch (rec.f[i].type) {
            case KV_STR:  json_string(&j, rec.f[i].val); break;
            case KV_NUM:  json_number(&j, rec.f[i].val); break;
            case KV_NULL: json_null(&j); break;
            }
        }
        json_end_object(&j);
    }
    json_end_array(&j);
    json_end_object(&j);

    ssize_t len = json_finish(&j);
    if (len < 0) {
        LOG_E("a reply of %zu bytes does not fit a %zu-byte response", n, r->cap);
        *why = "response did not fit";
        return false;
    }
    r->status = HTTP_STATUS_OK;
    r->ctype = "application/json";
    r->body_len = (size_t)len;
    return true;
}

/* ------------------------------------------------------------ the request line */

/* A query value is one token of a line sent to the source: nothing that could end a
 * string, start a field or a line, or surprise a parser. */
static bool safe_value(const char *v)
{
    size_t n = strlen(v);

    if (n == 0 || n > ROUTE_VALUE_MAX) return false;
    for (size_t i = 0; i < n; i++) {
        char c = v[i];
        bool ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
                  strchr(":+.,_/-", c) != NULL;
        if (!ok) return false;
    }
    return true;
}

/* Every key must be one of series_keys, at most once, and no pair may be empty. On success
 * sets bit i of *seen for each series_keys[i] present and returns NULL; else the reason. */
static const char *check_keys(const char *query, unsigned *seen)
{
    *seen = 0;
    for (const char *p = query; *p != '\0'; ) {
        size_t pair = strcspn(p, "&");
        size_t klen = strcspn(p, "=&");
        size_t k = 0;

        while (k < NSERIES_KEYS && !(strlen(series_keys[k]) == klen &&
                                     memcmp(p, series_keys[k], klen) == 0)) k++;
        if (k == NSERIES_KEYS) return "unknown query key";
        if (*seen & (1u << k)) return "repeated query key";
        *seen |= 1u << k;

        p += pair;
        if (*p == '&' && *++p == '\0') return "empty query pair";
    }
    return NULL;
}

/* series pid="0C" from="-5m" to=1800000000. pid is always a string (PID 04 has a leading
 * zero, and is no number); from and to are bare when they are all digits, epoch seconds.
 * Returns NULL, or the reason the URL was refused. */
static const char *build_series(const char *query, char *line, size_t cap)
{
    unsigned seen;
    const char *why = check_keys(query, &seen);
    size_t len = (size_t)snprintf(line, cap, "series");

    if (why != NULL) return why;
    for (size_t k = 0; k < NSERIES_KEYS; k++) {
        char v[HTTP_QUERY_MAX];

        if (!(seen & (1u << k))) continue;
        if (http_query_get(query, series_keys[k], v, sizeof v) != 0) return "bad query value";
        if (!safe_value(v)) return "unsafe query value";

        bool bare = k != 0 && strspn(v, "0123456789") == strlen(v);
        int w = snprintf(line + len, cap - len, bare ? " %s=%s" : " %s=\"%s\"", series_keys[k], v);
        if (w < 0 || (size_t)w >= cap - len) return "query too long";
        len += (size_t)w;
    }
    return NULL;
}

/* ------------------------------------------------------------------- handler */

void route_handle(void *ctx, const http_request_t *req, server_response_t *resp)
{
    route_ctx_t *rc = ctx;
    char line[ROUTE_LINE_MAX];
    const char *why = NULL;
    size_t found = NAPI;

    if (strcmp(req->path, "/") == 0) {
        if (req->query[0] != '\0') set_text(resp, HTTP_STATUS_BAD_REQUEST, "text/plain", "bad request\n");
        else set_text(resp, HTTP_STATUS_OK, "text/html; charset=utf-8", placeholder_page);
        return;
    }
    if (strncmp(req->path, "/api/", 5) != 0) {
        set_text(resp, HTTP_STATUS_NOT_FOUND, "text/plain", "not found\n");
        return;
    }
    for (size_t i = 0; i < NAPI; i++)
        if (strcmp(req->path, api[i].path) == 0) found = i;
    if (found == NAPI) {
        set_error(resp, HTTP_STATUS_NOT_FOUND, "not_found", "no such route");
        return;
    }

    if (strcmp(api[found].verb, "series") == 0) {
        why = build_series(req->query, line, sizeof line);
    } else if (req->query[0] != '\0') {
        why = "this route takes no query";
    } else {
        snprintf(line, sizeof line, "%s", api[found].verb);
    }
    if (why != NULL) {
        set_error(resp, HTTP_STATUS_BAD_REQUEST, "usage", why);
        return;
    }

    ssize_t n = source_query(rc->src, line, rc->reply, sizeof rc->reply);
    if (n < 0) {
        LOG_E("the source's reply to \"%s\" did not fit %u bytes", line, ROUTE_REPLY_MAX);
        set_error(resp, HTTP_STATUS_INTERNAL_ERROR, "internal", "reply did not fit");
        return;
    }

    kv_line_t final;
    switch (kv_reply_check(rc->reply, (size_t)n, &final)) {
    case KV_OK:
        if (!records_to_json(resp, rc->reply, (size_t)n, &why))
            set_error(resp, HTTP_STATUS_INTERNAL_ERROR, "internal", why);
        return;
    case KV_ERR:
        set_error(resp, status_for_code(final.err_code), final.err_code, final.err_reason);
        return;
    case KV_RECORD:
    case KV_BAD:
    case KV_INCOMPLETE:
        break;
    }
    LOG_E("the source's reply to \"%s\" is malformed", line);
    set_error(resp, HTTP_STATUS_INTERNAL_ERROR, "internal", "malformed source reply");
}

