            kill(started[i]->pid, SIGKILL);
            waitpid(started[i]->pid, NULL, 0);
            started[i]->pid = 0;
        }
    }
}

static void sleep_ms(int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* Reads whatever the child has printed, waiting up to ms for something. */
static void pump(proc_t *p, int ms)
{
    struct pollfd pf = { .fd = p->fd, .events = POLLIN };

    if (p->fd < 0 || poll(&pf, 1, ms) <= 0) return;
    for (;;) {
        ssize_t r = read(p->fd, p->log + p->len, sizeof p->log - 1 - p->len);
        if (r <= 0) break;
        p->len += (size_t)r;
    }
    p->log[p->len] = '\0';
}

static bool wait_for(proc_t *p, const char *needle, int ms)
{
    for (int waited = 0; waited <= ms; waited += 20) {
        if (strstr(p->log, needle) != NULL) return true;
        pump(p, 20);
    }
    return strstr(p->log, needle) != NULL;
}

static size_t occurrences(const char *hay, const char *needle)
{
    size_t n = 0;
    for (const char *s = hay; (s = strstr(s, needle)) != NULL; s += strlen(needle)) n++;
    return n;
}

/* Runs statusd with the given arguments (NULL-terminated). Stderr is dropped. */
static void start(proc_t *p, const char *const *args)
{
    char *argv[16] = { statusd_path };
    int fds[2];
    size_t n = 1;

    for (size_t i = 0; args[i] != NULL && n < 14; i++) argv[n++] = (char *)args[i];
    argv[n] = NULL;
    memset(p, 0, sizeof *p);
    if (pipe2(fds, O_CLOEXEC) < 0) { perror("pipe2"); exit(2); }

    p->pid = fork();
    if (p->pid < 0) { perror("fork"); exit(2); }
    if (p->pid == 0) {
        int null = open("/dev/null", O_WRONLY);
        dup2(fds[1], 1);
        if (null >= 0) dup2(null, 2);
        for (int fd = 3; fd < 256; fd++) close(fd);   /* nothing of the test's leaks in */
        execv(statusd_path, argv);
        _exit(127);
    }
    close(fds[1]);
    p->fd = fds[0];
    (void)fcntl(p->fd, F_SETFL, O_NONBLOCK);
    for (int i = 0; i < MAX_PROCS; i++)
        if (started[i] == NULL || started[i]->pid == 0) { started[i] = p; break; }
}

/* The exit code (128 + n for death by signal n), or -1 if it is still running after ms. */
static int wait_exit(proc_t *p, int ms)
{
    for (int waited = 0; waited <= ms; waited += 10) {
        int st;
        pid_t r = waitpid(p->pid, &st, WNOHANG);
        if (r == p->pid) {
            p->pid = 0;
            pump(p, 0);
            return WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
        }
        pump(p, 10);
    }
    return -1;
}

static void finish(proc_t *p)
{
    if (p->pid > 0) { kill(p->pid, SIGKILL); waitpid(p->pid, NULL, 0); p->pid = 0; }
    if (p->fd >= 0) { close(p->fd); p->fd = -1; }
}

/* Starts statusd on a free port and waits until it says it is listening. */
static uint16_t start_listening(proc_t *p, const char *const *extra)
{
    const char *args[10] = { "--bind", "127.0.0.1", "--port", "0" };
    size_t n = 4;

    for (size_t i = 0; extra != NULL && extra[i] != NULL && n < 8; i++) args[n++] = extra[i];
    args[n] = NULL;
    start(p, args);
    if (!wait_for(p, "listening on 127.0.0.1:", 5000)) {
        CHECK(false, "statusd never said it was listening");
        return 0;
    }
    const char *at = strstr(p->log, "listening on 127.0.0.1:") + strlen("listening on 127.0.0.1:");
    return (uint16_t)atoi(at);
}

/* ------------------------------------------------------------------- client */

static size_t get(uint16_t port, const char *request, char *out, size_t cap)
{
    struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(port) };
    struct timeval tv = { 3, 0 };
    size_t len = 0;
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);

    out[0] = '\0';
    if (fd < 0) return 0;
    inet_pton(AF_INET, "127.0.0.1", &a.sin_addr);
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof tv);
    if (connect(fd, (struct sockaddr *)&a, sizeof a) == 0 &&
        send(fd, request, strlen(request), MSG_NOSIGNAL) == (ssize_t)strlen(request)) {
        for (;;) {
            ssize_t r = recv(fd, out + len, cap - 1 - len, 0);
            if (r <= 0) break;
            len += (size_t)r;
        }
    }
    close(fd);
    out[len] = '\0';
    return len;
}

static int status_of(const char *r) { return strncmp(r, "HTTP/1.1 ", 9) == 0 ? atoi(r + 9) : -1; }

static char resp[65536];

static int fetch(uint16_t port, const char *path)
{
    char req[256];
    snprintf(req, sizeof req, "GET %s HTTP/1.1\r\nHost: test\r\n\r\n", path);
    get(port, req, resp, sizeof resp);
    return status_of(resp);
}

/* The newest "t_s" in the last response: the time of its latest sample. */
static unsigned long long latest_t_s(void)
{
    const char *last = NULL;
    for (const char *p = resp; (p = strstr(p, "\"t_s\":")) != NULL; p += 6) last = p + 6;
    return last != NULL ? strtoull(last, NULL, 10) : 0;
}

static bool can_bind(uint16_t port)
{
    struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(port) };
    int one = 1;
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    bool ok;

    inet_pton(AF_INET, "127.0.0.1", &a.sin_addr);
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
    ok = bind(fd, (struct sockaddr *)&a, sizeof a) == 0;
    close(fd);
    return ok;
}

/* ------------------------------------------------------------------- tests */

static void test_usage_errors(void)
{
    static const char *const bad[][4] = {
        { "--port", "abc", NULL }, { "--port", "70000", NULL }, { "--port", "-1", NULL },
        { "--port", "", NULL },    { "--port", "80x", NULL },   { "--port", NULL },
        { "--bind", "999.1.1.1", NULL }, { "--bind", "localhost", NULL }, { "--bind", NULL },
        { "--heartbeat-s", "0", NULL }, { "--heartbeat-s", "x", NULL }, { "--heartbeat-s", "86401", NULL },
        { "--nope", NULL }, { "stray", NULL },
    };
    proc_t p;

    for (size_t i = 0; i < sizeof bad / sizeof bad[0]; i++) {
        start(&p, bad[i]);
        int code = wait_exit(&p, 3000);
        if (code != 2) fprintf(stderr, "  (%s %s: exit %d)\n", bad[i][0], bad[i][1] ? bad[i][1] : "", code);
        CHECK(code == 2, "a bad argument is a usage error, exit 2");
        finish(&p);
    }

    const char *help[] = { "--help", NULL };
    start(&p, help);
    CHECK(wait_exit(&p, 3000) == 0, "--help exits 0");
    CHECK(strstr(p.log, "usage") != NULL, "and prints the usage");
    finish(&p);
}

static void test_port_taken_is_exit_1(void)
{
    proc_t a, b;
    uint16_t port = start_listening(&a, NULL);
    char num[16];
    const char *args[] = { "--bind", "127.0.0.1", "--port", num, NULL };

    snprintf(num, sizeof num, "%u", (unsigned)port);
    start(&b, args);
    CHECK(wait_exit(&b, 3000) == 1, "a port in use is a runtime failure, exit 1");
    CHECK(strstr(b.log, "bind") != NULL, "and the log says it was the bind");
    finish(&b);
    finish(&a);
}

static void test_lifecycle(void)
{
    static const char *const fast[] = { "--heartbeat-s", "1", NULL };
    proc_t p;
    uint16_t port = start_listening(&p, fast);

    CHECK(port != 0, "a port was chosen");
    const char *line = strstr(p.log, "listening on");
    const char *eol = line != NULL ? strchr(line, '\n') : NULL;
    CHECK(line != NULL && memmem(p.log, (size_t)(line - p.log), "src=synth", 9) != NULL,
          "the log line is labeled src=synth");
    CHECK(eol != NULL, "a whole line");
    CHECK(wait_for(&p, "heartbeat rss_kib=", 2000), "a heartbeat right at the start");

    CHECK(fetch(port, "/api/status") == 200 && strstr(resp, "\"src\":\"synth\"") != NULL,
          "the API answers with synthetic records");
    CHECK(fetch(port, "/") == 200 && strstr(resp, "statusd") != NULL, "and the page");
    get(port, "GARBAGE\r\n\r\n", resp, sizeof resp);
    CHECK(status_of(resp) == 400, "garbage is a 400");
    CHECK(fetch(port, "/api/faults") == 200, "and the server carries on");

    /* The synthetic source is driven by the real clock, and the clock moves. */
    CHECK(fetch(port, "/api/series?pid=0C") == 200, "a series");
    unsigned long long t1 = latest_t_s(), now = (unsigned long long)time(NULL);
    CHECK(t1 + 310 >= now && t1 <= now + 2, "its latest sample is from now");
    pump(&p, 0);
    sleep_ms(2500);
    CHECK(fetch(port, "/api/series?pid=0C") == 200 && latest_t_s() > t1,
          "and a later request has later samples");
    pump(&p, 100);
    CHECK(occurrences(p.log, "heartbeat rss_kib=") >= 3, "a heartbeat every second asked for");

    /* Descriptors: the listener, and nothing else beyond stdio, all close-on-exec. */
    char dir[64];
    snprintf(dir, sizeof dir, "/proc/%d/fd", (int)p.pid);
    DIR *d = opendir(dir);
    int open_fds = 0;
    struct dirent *e;
    while (d != NULL && (e = readdir(d)) != NULL) {
        int fd = atoi(e->d_name);
        if (e->d_name[0] == '.' || fd <= 2) continue;
        open_fds++;
        char info[64], buf[256];
        snprintf(info, sizeof info, "/proc/%d/fdinfo/%d", (int)p.pid, fd);
        FILE *f = fopen(info, "r");
        unsigned long flags = 0;
        while (f != NULL && fgets(buf, sizeof buf, f) != NULL)
            if (sscanf(buf, "flags: %lo", &flags) == 1) break;
        if (f != NULL) fclose(f);
        CHECK((flags & 02000000UL) != 0, "every descriptor is close-on-exec");
    }
    if (d != NULL) closedir(d);
    CHECK(d != NULL && open_fds == 1, "only the listening socket is open besides stdio");

    kill(p.pid, SIGTERM);
    CHECK(wait_exit(&p, 2000) == 0, "SIGTERM is a clean exit, 0");
    CHECK(strstr(p.log, "stop served=") != NULL, "and it logs the stop");
    CHECK(can_bind(port), "and the port is free at once");
    finish(&p);
}

static void test_other_signals(void)
{
    proc_t p;
    uint16_t port = start_listening(&p, NULL);

    kill(p.pid, SIGINT);
    CHECK(wait_exit(&p, 2000) == 0, "SIGINT is a clean exit too");
    CHECK(can_bind(port), "port free after SIGINT");
    finish(&p);

    port = start_listening(&p, NULL);
    kill(p.pid, SIGKILL);
    CHECK(wait_exit(&p, 2000) == 128 + SIGKILL, "SIGKILL kills it");
    CHECK(can_bind(port), "and leaves nothing holding the port");
    finish(&p);
}

int main(void)
{
    ssize_t n = readlink("/proc/self/exe", statusd_path, sizeof statusd_path - 16);
    char *slash;

    if (n <= 0) { perror("readlink"); return 2; }
    statusd_path[n] = '\0';
    slash = strrchr(statusd_path, '/');
    if (slash == NULL) return 2;
    strcpy(slash + 1, "statusd");

    signal(SIGPIPE, SIG_IGN);
    atexit(kill_all);
    alarm(90);                       /* the whole test, however it hangs */

    test_usage_errors();
    test_port_taken_is_exit_1();
    test_lifecycle();
    test_other_signals();
    return failures == 0 ? 0 : 1;
}

/* statusd: the phone page and API (D-013, D-043, D-045).
 *
 * A supervisable daemon (CLAUDE.md section 2.6): it exits 0 on SIGTERM or SIGINT, 1 when it
 * cannot run, 2 on bad arguments; it holds no descriptor but its listener (close-on-exec);
 * it logs a heartbeat at once and then every --heartbeat-s seconds; and nothing it does
 * depends on a sibling being alive, so a kill -9 of any other daemon changes nothing here.
 *
 * It serves only the box's own access-point address, never every interface: --bind has no
 * default but loopback. Until the real source exists it answers from the synthetic one,
 * and says so on every log line (src=synth).
 */
#include "common/log.h"
#include "interface/route.h"
#include "interface/server.h"
#include "interface/synth_source.h"

#include <arpa/inet.h>
#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define DEFAULT_BIND         "127.0.0.1"
#define DEFAULT_PORT         8080u
#define DEFAULT_HEARTBEAT_S  3600u
#define MAX_HEARTBEAT_S      86400u

typedef struct {
    const char *bind;
    uint16_t    port;
    unsigned    heartbeat_s;
} args_t;

typedef enum { ARGS_OK, ARGS_HELP, ARGS_USAGE } args_result_t;

static volatile sig_atomic_t g_stop;

static void on_signal(int sig)
{
    g_stop = sig;
}

/* ------------------------------------------------------------------ arguments */

static void usage(FILE *to)
{
    fprintf(to,
            "usage: statusd [--bind ADDR] [--port N] [--heartbeat-s N]\n"
            "  --bind ADDR       IPv4 address to serve on (default " DEFAULT_BIND ")\n"
            "  --port N          TCP port, 0 for any free one (default %u)\n"
            "  --heartbeat-s N   seconds between heartbeat log lines, 1 to %u (default %u)\n"
            "exit status: 0 stopped by SIGTERM or SIGINT, 1 could not run, 2 bad arguments\n",
            DEFAULT_PORT, MAX_HEARTBEAT_S, DEFAULT_HEARTBEAT_S);
}

/* s is wholly decimal digits and at most max. */
static bool parse_number(const char *s, unsigned long max, unsigned long *out)
{
    char *end;

    if (s[0] < '0' || s[0] > '9') return false;     /* no sign, no space, not empty */
    errno = 0;
    *out = strtoul(s, &end, 10);
    return errno == 0 && *end == '\0' && *out <= max;
}

static args_result_t parse_args(int argc, char **argv, args_t *a)
{
    a->bind = DEFAULT_BIND;
    a->port = (uint16_t)DEFAULT_PORT;
    a->heartbeat_s = DEFAULT_HEARTBEAT_S;

    for (int i = 1; i < argc; i++) {
        const char *flag = argv[i];
        unsigned long n;

        if (strcmp(flag, "--help") == 0 || strcmp(flag, "-h") == 0) {
            usage(stdout);
            return ARGS_HELP;
        }
        if (i + 1 >= argc || (strcmp(flag, "--bind") != 0 && strcmp(flag, "--port") != 0 &&
                              strcmp(flag, "--heartbeat-s") != 0)) {
            fprintf(stderr, "statusd: %s: %s\n", flag,
                    i + 1 >= argc && strncmp(flag, "--", 2) == 0 ? "needs a value" : "unknown argument");
            usage(stderr);
            return ARGS_USAGE;
        }
        const char *value = argv[++i];

        if (strcmp(flag, "--bind") == 0) {
            struct in_addr probe;
            if (inet_pton(AF_INET, value, &probe) != 1) {
                fprintf(stderr, "statusd: --bind: %s is not an IPv4 address\n", value);
                return ARGS_USAGE;
            }
            a->bind = value;
        } else if (strcmp(flag, "--port") == 0) {
            if (!parse_number(value, 65535, &n)) {
                fprintf(stderr, "statusd: --port: %s is not 0 to 65535\n", value);
                return ARGS_USAGE;
            }
            a->port = (uint16_t)n;
        } else {
            if (!parse_number(value, MAX_HEARTBEAT_S, &n) || n == 0) {
                fprintf(stderr, "statusd: --heartbeat-s: %s is not 1 to %u\n", value, MAX_HEARTBEAT_S);
                return ARGS_USAGE;
            }
            a->heartbeat_s = (unsigned)n;
        }
    }
    return ARGS_OK;
}

/* ---------------------------------------------------------------------- clocks */

static uint64_t wall_seconds(void)
{
    static uint64_t last;
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) LOG_E("clock_gettime: %s", strerror(errno));
    else last = (uint64_t)ts.tv_sec;
    return last;
}

static uint64_t mono_ms(void)
{
    struct timespec ts;

    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        LOG_E("clock_gettime: %s", strerror(errno));
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u;
}

/* ----------------------------------------------------------------- the source */

/* The synthetic source, moved to the real time before each request, so that its samples
 * are from now and keep moving. The real source (a client of ctl.sock) replaces this whole
 * struct, and route.c never knows which it has. */
typedef struct {
    synth_t  synth;
    source_t inner;
    source_t outer;
} live_source_t;

static ssize_t clocked_query(void *ctx, const char *request, char *out, size_t cap)
{
    live_source_t *l = ctx;

    synth_set_time(&l->synth, wall_seconds());
    return source_query(&l->inner, request, out, cap);
}

/* ---------------------------------------------------------------------- setup */

static int install_signals(void)
{
    struct sigaction stop = { .sa_handler = on_signal };   /* no SA_RESTART: poll must return */
    struct sigaction ignore = { .sa_handler = SIG_IGN };

    sigemptyset(&stop.sa_mask);
    sigemptyset(&ignore.sa_mask);
    if (sigaction(SIGTERM, &stop, NULL) < 0 || sigaction(SIGINT, &stop, NULL) < 0) {
        LOG_E("sigaction: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGPIPE, &ignore, NULL) < 0) {
        LOG_E("sigaction SIGPIPE: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* About 280 KB between them, so they live in static storage, not on the stack. */
static server_t      srv;
static route_ctx_t   rc;
static live_source_t live;

int main(int argc, char **argv)
{
    args_t args;
    int status = 0;

    switch (parse_args(argc, argv, &args)) {
    case ARGS_OK:    break;
    case ARGS_HELP:  return 0;
    case ARGS_USAGE: return 2;
    }

    log_init("statusd", LOG_INFO);
    log_set_src(SRC_SYNTH);             /* every line says so, while the data is made up */

    if (install_signals() < 0) return 1;

    synth_init(&live.synth, wall_seconds());
    live.inner = synth_source(&live.synth);
    live.outer = (source_t){ .query = clocked_query, .ctx = &live };
    rc.src = &live.outer;

    if (server_open(&srv, args.bind, args.port, route_handle, &rc) < 0) return 1;

    uint64_t every_ms = (uint64_t)args.heartbeat_s * 1000u;
    uint64_t next_heartbeat = mono_ms() + every_ms;

    log_heartbeat(server_served(&srv), server_drops(&srv));   /* alive, from the first second */
    while (!g_stop) {
        if (server_step(&srv, 1000) < 0) {
            LOG_E("the server failed; exiting");
            status = 1;
            break;
        }
        if (mono_ms() >= next_heartbeat) {
            log_heartbeat(server_served(&srv), server_drops(&srv));
            next_heartbeat = mono_ms() + every_ms;
        }
    }

    if (g_stop) LOG_I("signal %d: stopping", (int)g_stop);
    server_close(&srv);
    return status;
}

