import re
p = "tests/test_statusd.c"
s = open(p).read()

# 1. a monotonic clock, and pump() reports how much it read
s = s.replace('''static void sleep_ms(int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}
''', '''static void sleep_ms(int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static uint64_t now_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u;
}
''')

s = s.replace('''/* Reads whatever the child has printed, waiting up to ms for something. */
static void pump(proc_t *p, int ms)
{
    struct pollfd pf = { .fd = p->fd, .events = POLLIN };

    if (p->fd < 0 || poll(&pf, 1, ms) <= 0) return;
    for (;;) {
        ssize_t r = read(p->fd, p->log + p->len, sizeof p->log - 1 - p->len);
        if (r <= 0) break;
        p->len += (size_t)r;
    }
    p->log[p->len] = '\\0';
}

static bool wait_for(proc_t *p, const char *needle, int ms)
{
    for (int waited = 0; waited <= ms; waited += 20) {
        if (strstr(p->log, needle) != NULL) return true;
        pump(p, 20);
    }
    return strstr(p->log, needle) != NULL;
}''', '''/* Reads whatever the child has printed, waiting up to ms for something. Returns the
 * bytes read. After the child closes its stdout poll() answers at once for ever, so
 * callers that wait must not count on pump() to take time. */
static size_t pump(proc_t *p, int ms)
{
    struct pollfd pf = { .fd = p->fd, .events = POLLIN };
    size_t before = p->len;

    if (p->fd < 0 || poll(&pf, 1, ms) <= 0) return 0;
    for (;;) {
        ssize_t r = read(p->fd, p->log + p->len, sizeof p->log - 1 - p->len);
        if (r <= 0) break;
        p->len += (size_t)r;
    }
    p->log[p->len] = '\\0';
    return p->len - before;
}

/* Waits on the real clock, not on a count of loops. */
static bool wait_for(proc_t *p, const char *needle, int ms)
{
    uint64_t end = now_ms() + (uint64_t)ms;

    while (strstr(p->log, needle) == NULL && now_ms() < end)
        if (pump(p, 20) == 0) sleep_ms(5);
    return strstr(p->log, needle) != NULL;
}''')

s = s.replace('''static int wait_exit(proc_t *p, int ms)
{
    for (int waited = 0; waited <= ms; waited += 10) {
        int st;
        pid_t r = waitpid(p->pid, &st, WNOHANG);
        if (r == p->pid) {
            p->pid = 0;
            pump(p, 0);
            return WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
        }
        pump(p, 10);
    }
    return -1;
}''', '''static int wait_exit(proc_t *p, int ms)
{
    uint64_t end = now_ms() + (uint64_t)ms;

    do {
        int st;
        pid_t r = waitpid(p->pid, &st, WNOHANG);
        if (r == p->pid) {
            p->pid = 0;
            pump(p, 0);
            return WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
        }
        if (pump(p, 10) == 0) sleep_ms(5);
    } while (now_ms() < end);
    return -1;
}''')
open(p, "w").write(s)
EOF
